CREATE TABLE IF NOT EXISTS "ipo_events" ("id" TEXT NOT NULL,"symbol" TEXT NOT NULL,"companyName" TEXT NOT NULL,"nameAr" TEXT NOT NULL,"market" TEXT NOT NULL,"ipoDate" TIMESTAMP(3) NOT NULL,"priceRange" TEXT NOT NULL,"sharesOffered" BIGINT NOT NULL,"totalValue" DOUBLE PRECISION NOT NULL,"status" TEXT NOT NULL,"subscriptionStart" TIMESTAMP(3),"subscriptionEnd" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ipo_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "ipo_events_ipoDate_idx" ON "ipo_events"("ipoDate");
CREATE TABLE IF NOT EXISTS "dividend_events" ("id" TEXT NOT NULL,"symbol" TEXT NOT NULL,"market" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"currency" TEXT NOT NULL,"exDate" TIMESTAMP(3) NOT NULL,"recordDate" TIMESTAMP(3) NOT NULL,"paymentDate" TIMESTAMP(3) NOT NULL,"yieldPercent" DOUBLE PRECISION NOT NULL,"status" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "dividend_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "dividend_events_exDate_idx" ON "dividend_events"("exDate");
CREATE TABLE IF NOT EXISTS "earnings_events" ("id" TEXT NOT NULL,"symbol" TEXT NOT NULL,"market" TEXT NOT NULL,"quarter" TEXT NOT NULL,"fiscalYear" INTEGER NOT NULL,"reportDate" TIMESTAMP(3) NOT NULL,"timeOfDay" TEXT NOT NULL,"epsEstimate" DOUBLE PRECISION,"epsActual" DOUBLE PRECISION,"revenueEstimate" DOUBLE PRECISION,"revenueActual" DOUBLE PRECISION,"surprise" DOUBLE PRECISION,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "earnings_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "earnings_events_reportDate_idx" ON "earnings_events"("reportDate");
CREATE TABLE IF NOT EXISTS "split_events" ("id" TEXT NOT NULL,"symbol" TEXT NOT NULL,"market" TEXT NOT NULL,"splitDate" TIMESTAMP(3) NOT NULL,"ratio" TEXT NOT NULL,"oldShares" BIGINT NOT NULL,"newShares" BIGINT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "split_events_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "split_events_splitDate_idx" ON "split_events"("splitDate");
CREATE TABLE IF NOT EXISTS "insider_trades" ("id" TEXT NOT NULL,"symbol" TEXT NOT NULL,"insiderName" TEXT NOT NULL,"insiderRole" TEXT NOT NULL,"transactionType" TEXT NOT NULL,"shares" INTEGER NOT NULL,"price" DOUBLE PRECISION NOT NULL,"totalValue" DOUBLE PRECISION NOT NULL,"transactionDate" TIMESTAMP(3) NOT NULL,"filingDate" TIMESTAMP(3) NOT NULL,"source" TEXT NOT NULL,CONSTRAINT "insider_trades_pkey" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "insider_trades_symbol_transactionDate_idx" ON "insider_trades"("symbol","transactionDate");
